import os


def get_extension(path: str) -> str:
    """Return the file extension including the dot, e.g. '.txt'."""
    _, ext = os.path.splitext(path)
    return ext


def get_stem(path: str) -> str:
    """Return filename without extension."""
    return os.path.splitext(os.path.basename(path))[0]


def join_paths(*parts: str) -> str:
    """Join path components."""
    return os.path.join(*parts)


def is_absolute(path: str) -> bool:
    """Return True if the path is absolute."""
    return os.path.isabs(path)


def parent_dir(path: str) -> str:
    """Return the parent directory of the given path."""
    return os.path.dirname(path)

from src.fileutils import get_extension, get_stem, join_paths, is_absolute, parent_dir


def test_get_extension():
    assert get_extension("/tmp/report.txt") == ".txt"
    assert get_extension("archive.tar.gz") == ".gz"


def test_get_stem():
    assert get_stem("/home/user/notes.md") == "notes"
    assert get_stem("script.py") == "script"


def test_join_paths():
    assert join_paths("/home", "user", "docs") == "/home/user/docs"


def test_is_absolute():
    assert is_absolute("/etc/passwd")
    assert not is_absolute("relative/path")


def test_parent_dir():
    assert parent_dir("/home/user/file.txt") == "/home/user"

